+type byAttrName []*Attribute
+
+func (a byAttrName) Len() int           { return len(a) }
+func (a byAttrName) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
+func (a byAttrName) Less(i, j int) bool { return a[i].Name < a[j].Name }
