+func (b *tabButton) CreateRenderer() fyne.WidgetRenderer {
+	b.ExtendBaseWidget(b)
+	background := canvas.NewRectangle(theme.HoverColor())
+	background.Hide()
+	var icon *canvas.Image
+	if b.icon != nil {
+		icon = canvas.NewImageFromResource(b.icon)
