+func (r *tabButtonRenderer) padding() fyne.Size {
+	if r.label.Text != "" && r.button.iconPosition == buttonIconInline {
+		return fyne.NewSize(theme.Padding()*4, theme.Padding()*4)
+	}
+	return fyne.NewSize(theme.Padding()*2, theme.Padding()*4)
